BEGIN;
CREATE TABLE IF NOT EXISTS industry_packs (id bigserial PRIMARY KEY, code text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS intent_families (id bigserial PRIMARY KEY, code text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commerce_intents (id bigserial PRIMARY KEY, code text NOT NULL UNIQUE, family_id bigint NOT NULL REFERENCES intent_families(id), description text NOT NULL, action_type text NOT NULL DEFAULT 'INTERPRET', risk_level text NOT NULL CHECK(risk_level IN ('LOW','HIGH')), requires_confirmation boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS semantic_groups (id bigserial PRIMARY KEY, code text NOT NULL UNIQUE, category text NOT NULL, description text NOT NULL DEFAULT '', value_type text NOT NULL DEFAULT 'CONCEPT', active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS semantic_terms (id bigserial PRIMARY KEY, semantic_group_id bigint NOT NULL REFERENCES semantic_groups(id) ON DELETE CASCADE, term text NOT NULL, normalized_term text NOT NULL CHECK(length(normalized_term)>0), term_type text NOT NULL DEFAULT 'PHRASE', weight real NOT NULL DEFAULT 1 CHECK(weight>0), frequency_class text NOT NULL DEFAULT 'COMMON' CHECK(frequency_class IN ('VERY_COMMON','COMMON','MODERATE','RARE')), exact_match boolean NOT NULL DEFAULT true, fuzzy_allowed boolean NOT NULL DEFAULT false, priority integer NOT NULL DEFAULT 0, industry_id bigint REFERENCES industry_packs(id), active boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(semantic_group_id,normalized_term));
CREATE INDEX IF NOT EXISTS semantic_terms_normalized_idx ON semantic_terms(normalized_term);
CREATE TABLE IF NOT EXISTS intent_rules (id bigserial PRIMARY KEY, intent_id bigint NOT NULL REFERENCES commerce_intents(id) ON DELETE CASCADE, base_score real NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS intent_rules_intent_idx ON intent_rules(intent_id);
CREATE TABLE IF NOT EXISTS intent_rule_conditions (id bigserial PRIMARY KEY, rule_id bigint NOT NULL REFERENCES intent_rules(id) ON DELETE CASCADE, semantic_group_id bigint NOT NULL REFERENCES semantic_groups(id), kind text NOT NULL CHECK(kind IN ('REQUIRED','OPTIONAL','POSITIVE','BOOST','NEGATIVE','DISQUALIFY')), score real NOT NULL, occurrences integer NOT NULL DEFAULT 1 CHECK(occurrences>0), proximity integer CHECK(proximity>=0), after_group_id bigint REFERENCES semantic_groups(id), active boolean NOT NULL DEFAULT true);
CREATE INDEX IF NOT EXISTS conditions_rule_idx ON intent_rule_conditions(rule_id);
CREATE TABLE IF NOT EXISTS entity_types (id bigserial PRIMARY KEY, code text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS entity_aliases (id bigserial PRIMARY KEY, entity_type_id bigint NOT NULL REFERENCES entity_types(id), alias text NOT NULL, normalized_alias text NOT NULL, canonical_value text NOT NULL, industry_id bigint REFERENCES industry_packs(id), active boolean NOT NULL DEFAULT true, UNIQUE(entity_type_id,normalized_alias));
CREATE INDEX IF NOT EXISTS aliases_normalized_idx ON entity_aliases(normalized_alias);
CREATE TABLE IF NOT EXISTS commerce_operators (id bigserial PRIMARY KEY, code text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS phrase_patterns (id bigserial PRIMARY KEY, intent_id bigint NOT NULL REFERENCES commerce_intents(id), groups jsonb NOT NULL, score real NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS context_states (id bigserial PRIMARY KEY, code text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS intent_transition_rules (id bigserial PRIMARY KEY, previous_intent_id bigint NOT NULL REFERENCES commerce_intents(id), target_intent_id bigint NOT NULL REFERENCES commerce_intents(id), semantic_group_id bigint NOT NULL REFERENCES semantic_groups(id), required_states jsonb NOT NULL DEFAULT '[]', boost real NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE INDEX IF NOT EXISTS transitions_lookup_idx ON intent_transition_rules(previous_intent_id,semantic_group_id);
CREATE TABLE IF NOT EXISTS intent_conflicts (intent_id bigint NOT NULL REFERENCES commerce_intents(id), conflicting_intent_id bigint NOT NULL REFERENCES commerce_intents(id), penalty real NOT NULL DEFAULT 4, PRIMARY KEY(intent_id,conflicting_intent_id), CHECK(intent_id<>conflicting_intent_id));
CREATE TABLE IF NOT EXISTS generated_utterances (id bigserial PRIMARY KEY, text text NOT NULL, expected_intent_id bigint REFERENCES commerce_intents(id), difficulty text NOT NULL CHECK(difficulty IN ('EASY','MEDIUM','HARD','AMBIGUOUS','CONTEXT_REQUIRED','NEGATIVE_CONFLICT','TYPO_NOISE')), context jsonb NOT NULL DEFAULT '{}', expected_entities jsonb NOT NULL DEFAULT '{}', expected_status text NOT NULL DEFAULT 'RESOLVED');
CREATE TABLE IF NOT EXISTS evaluation_results (id bigserial PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), dictionary_version integer NOT NULL, metrics jsonb NOT NULL);
COMMIT;
